"""Write the SYNTHETIC QAC-format fixture used by tests and the CI build.

QAC's terms allow only verbatim copies of its file, so no excerpt of it is
committed. This script derives a file in the same format from the committed
Tanzil fixture text, mechanically: a word starting with "وَ" gets a w:CONJ+
prefix, one starting with "ٱل" an Al+ prefix, everything else is one stem.
Tags, lemmas and roots are placeholders and NOT linguistically correct.
Tatweel is dropped from the forms, as QAC writes them, so the fixture also
exercises the "canonical" alignment level.

Run: uv run python tests/fixtures/make_synthetic_qac.py
"""

from __future__ import annotations

from pathlib import Path

from pipeline.align import tanzil_words
from pipeline.buckwalter import to_buckwalter
from pipeline.qac import COLUMNS
from pipeline.tanzil import parse_quran_xml

HERE = Path(__file__).parent
SOURCE = HERE / "cache" / "tanzil" / "quran-uthmani.xml"
OUT = HERE / "cache" / "morphology.qac" / "quranic-corpus-morphology-0.4.txt"
HEADER = """\
# SYNTHETIC TEST DATA - NOT FROM THE QURANIC ARABIC CORPUS.
#
# Generated by tests/fixtures/make_synthetic_qac.py from the Tanzil fixture text,
# in the format of quranic-corpus-morphology-0.4.txt. Segmentation, tags,
# lemmas and roots are mechanical placeholders and are not linguistically correct.
"""
WA, AL = "\u0648\u064e", "\u0671\u0644"
CONSONANTS = set("'>&<}AbptvjHxd*rzs$SDTZEgfqklmnhwYy{")


def segments(word: str) -> list[tuple[str, str, str]]:
    """(form, tag, features) for one word."""
    form = to_buckwalter(word.replace("\u0640", ""))
    rows: list[tuple[str, str, str]] = []
    if word.startswith(WA) and len(word) > 3:
        rows.append(("wa", "CONJ", "PREFIX|w:CONJ+"))
        form = form[2:]
    elif word.startswith(AL) and len(word) > 3:
        rows.append(("{l", "DET", "PREFIX|Al+"))
        form = form[2:]
    root = "".join(ch for ch in form if ch in CONSONANTS)[:3]
    features = f"STEM|POS:N|LEM:{form}" + (f"|ROOT:{root}" if len(root) == 3 else "") + "|GEN"
    rows.append((form, "N", features))
    return rows


def main() -> None:
    lines = [HEADER.rstrip("\n"), COLUMNS]
    for aya in parse_quran_xml(SOURCE).verses:
        for word in tanzil_words(aya.text, f"{aya.surah}:{aya.ayah}"):
            for index, (form, tag, features) in enumerate(segments(word.token), start=1):
                location = f"({aya.surah}:{aya.ayah}:{word.position}:{index})"
                lines.append(f"{location}\t{form}\t{tag}\t{features}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
